importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.4.1/workbox-sw.js');

if (workbox) {
  console.log(`Workbox version ${workbox.core.version}`);

  // Precache any assets generated by the build process (next-pwa will inject __WB_MANIFEST)
  workbox.precaching.precacheAndRoute(self.__WB_MANIFEST || []);

  // Cache HTML pages with NetworkFirst strategy
  workbox.routing.registerRoute(
    ({request}) => request.destination === 'document',
    new workbox.strategies.NetworkFirst()
  );

  // Cache CSS, JS, images with CacheFirst strategy
  workbox.routing.registerRoute(
    ({request}) => request.destination === 'style' || request.destination === 'script' || request.destination === 'image',
    new workbox.strategies.CacheFirst()
  );

  // Cache API requests with NetworkFirst (fetch from network, fallback to cache)
  workbox.routing.registerRoute(
    ({url}) => url.pathname.startsWith('/api/'),
    new workbox.strategies.NetworkFirst()
  );

  // Optional: fallback to offline page for navigations
  // workbox.routing.setCatchHandler(({event}) => {
  //   switch (event.request.destination) {
  //     case 'document':
  //       return caches.match('/offline.html');
  //     default:
  //       return Response.error();
  //   }
  // });
} else {
  console.error('Workbox could not be loaded. No Offline support');
}

// Import OneSignal SDK worker (must be last)
importScripts('/OneSignalSDKWorker.js');